import java.io.*;
import java.util.*;

import jakarta.servlet.*;
import jakarta.servlet.annotation.*;
import jakarta.servlet.http.*;
import com.bisangoding.web.*;

public class Main {
    public static void main(String[] args) {
        ServerUji server = new ServerUji();
        server.tambah(new HitungServlet());
        Scanner in = new Scanner(System.in);
        while (in.hasNextLine()) {
            server.cetak("GET", in.nextLine());
        }
    }
}

@WebServlet("/hitung")
class HitungServlet extends HttpServlet {
    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse res) throws IOException {
        String ta = req.getParameter("a");
        String tb = req.getParameter("b");
        if (ta == null || tb == null) {
            res.sendError(400, "parameter a dan b wajib diisi");
            return;
        }
        int a;
        int b;
        try {
            a = Integer.parseInt(ta);
            b = Integer.parseInt(tb);
        } catch (NumberFormatException e) {
            res.sendError(400, "a dan b harus angka");
            return;
        }
        res.setContentType("text/plain;charset=UTF-8");
        res.getWriter().print(a + b);
    }
}
